import { mapGetters } from 'vuex'
import { getVideoByPage } from '@/api/xcnanr/roomRecordLog'

export default {
  name: 'RoomRecordVideo',
  computed: { ...mapGetters(["permission", "userInfo", 'userDetail']),
    permissionList() {
      return {}
    }},
  data() {
    return {
      searchForm: {
        workCode: null,
        workerName: null,
        operateDevice: null,
        pageNo: 1,
        pageSize: 10,
      },
      total: 0,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false
    }
  },
  mounted() {
    this.setPageContentHeight()
    this.setTableHeight()
    this.getList()
  },
  methods: {
    showVideo(row)   {
      window.open(row.ossAddress, '_blank');
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body')
      this.tableHeight = (bodyBox[0].offsetHeight - 100) + 'px'
    },
    queryEvent() {
      this.searchForm.pageNo = 1;
      this.searchForm.pageSize = 10;
      this.getList()
    },
    resetEvent() {
      this.searchForm = {
        workCode: null,
        workerName: null,
        operateDevice: null,
        pageNo: 1,
        pageSize: 10,
      }
      this.getList()
    },
    getList() {
      this.tableLoading = true
      // 处理时间范围
      getVideoByPage(this.searchForm).then(res => {
        this.tableData = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    }
  }
}
